async function api(body){
 return new Promise((resolve,reject)=>{
  const timer=setTimeout(()=>reject(new Error('서버 응답 시간이 초과되었습니다.')),15000);
  google.script.run
   .withSuccessHandler(result=>{clearTimeout(timer);resolve(result)})
   .withFailureHandler(error=>{clearTimeout(timer);reject(new Error(error&&error.message?error.message:String(error)))})
   .apiRequest(JSON.stringify({...body,password,accessToken}));
 });
}
function setSync(cls,text){const x=$('#syncState');x.className='sync '+cls;x.textContent='● '+text}
function syncTime(){return new Date().toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}
async function sync(){
 if(syncPromise)return syncPromise;
 syncPromise=(async()=>{
  if(!accessToken||!navigator.onLine){setSync('off',`오프라인 저장 · 대기 ${db.queue.length}건`);return}
  try{
   setSync('','시트 확인 중');
   if(db.queue.length){
    const q=[...db.queue],r=await api({action:'push',operations:q});
    if(!r.ok)throw Error(r.error);
    db.queue=db.queue.slice(q.length);
    saveLocal();
    // 전송 중 새 입력이 들어온 경우, 새 기록을 보존하고 다음 동기화에서 이어서 보냅니다.
    if(db.queue.length){setSync('','추가 기록 전송 준비');return}
   }
   const pulled=await api({action:'pull'});
   if(!pulled.ok)throw Error(pulled.error);
   // 정상 연결 시 휴대전화의 과거 복사본이 아니라 시트의 현재 전체 자료로 교체합니다.
   mergeRemote(pulled.data||{});mergeMedicine(pulled.data||{});
   saveLocal();
   setSync('ok','시트 최신 · '+syncTime()+' · '+APP_VERSION);
   if(!reportOpen&&!formEditing)render();
  }catch(e){saveLocal();setSync('off',navigator.onLine?`동기화 실패 · 대기 ${db.queue.length}건`:`오프라인 저장 · 대기 ${db.queue.length}건`)}
 })();
 try{return await syncPromise}finally{syncPromise=null;if(db.queue.length&&navigator.onLine)setTimeout(sync,250)}
}
