 const grid=[0,.25,.5,.75,1].map(r=>{const y=T+plotH*(1-r);return `<line x1="${L}" y1="${y}" x2="${W-R}" y2="${y}" stroke="#dfe8e2" stroke-width="1"/><text x="${L-5}" y="${y+3}" text-anchor="end" font-size="8" fill="#6b776f">${Math.round(maxValue*r)}</text>`}).join('');
 const chart=`<div class="card" style="padding:10px"><div style="display:flex;justify-content:space-between;align-items:flex-end"><div><b>일령별 폐·도태 추이</b><small style="display:block;color:#68736c">${graphHouse?graphHouse+'동':'1~5동 합계'} · 점을 누르면 상세표시</small></div><strong style="color:${color}">${ca}일령 ${fmt(values[ca-1])}수</strong></div><svg viewBox="0 0 ${W} ${H}" style="display:block;width:100%;height:auto;margin-top:5px" aria-label="일령별 폐사 도태 추이 그래프">${grid}<path d="${path}" fill="none" stroke="${color}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${points.map((p,i)=>`<circle data-graph-age="${i+1}" cx="${p.x}" cy="${p.y}" r="${graphPointAge===i+1?5:3}" fill="${graphPointAge===i+1?'#fff':color}" stroke="${color}" stroke-width="2" style="cursor:pointer"/>`).join('')}<text x="${L}" y="${H-5}" font-size="9" fill="#68736c">1일령</text><text x="${W-R}" y="${H-5}" text-anchor="end" font-size="9" fill="#68736c">${ca}일령</text></svg><div style="display:grid;grid-template-columns:repeat(3,1fr);border-radius:9px;background:${graphHouse?SOFT[graphHouse-1]:'#edf7f0'};padding:8px 3px;text-align:center;font-size:10px"><span><b>${graphPointAge}일령</b><br>선택 일령</span><span>폐사<br><b style="font-size:15px;color:${color}">${fmt(selectedDay.death)}</b></span><span>도태<br><b style="font-size:15px;color:${color}">${fmt(selectedDay.cull)}</b></span></div></div>`;
