 const losses=[1,2,3,4,5].map(h=>cumulative(h,'death')+cumulative(h,'cull')),lossMax=Math.max(1,...losses),lossBars=`<div class="card" style="padding:10px"><b>동별 누적 폐·도태 비교</b><small style="display:block;color:#68736c">현재 ${ca}일령 기준</small><div style="margin-top:9px">${losses.map((v,i)=>`<div style="display:grid;grid-template-columns:34px 1fr 50px;gap:7px;align-items:center;margin:7px 0;font-size:11px"><b style="background:${COLORS[i]};color:#fff;border-radius:6px;padding:5px 2px;text-align:center">${i+1}동</b><i style="height:10px;background:#e7ece9;border-radius:9px;overflow:hidden"><em style="display:block;width:${v?Math.max(2,v/lossMax*100):0}%;height:100%;background:${COLORS[i]};border-radius:9px"></em></i><strong style="text-align:right;color:${COLORS[i]}">${fmt(v)}수</strong></div>`).join('')}</div></div>`;
