function shipView(){page('부분출하','출하 즉시 현재 사육수에 반영',`<div class="card"><div class="houses">${[1,2,3,4,5].map(h=>`<button style="--c:${COLORS[h-1]}" data-house="${h}" class="${selected===h?'active':''}">${h}동</button>`).join('')}</div><div class="number-grid"><label>부분출하수<input id="shipCount" type="number" inputmode="numeric" min="0"></label><label>출하일<input id="shipDate" type="date" value="${today()}"></label></div><label class="field">특이사항<textarea id="shipNote"></textarea></label><button id="saveShip" class="save" style="--house:${COLORS[selected-1]}">${selected}동 부분출하 저장</button></div><div class="card records"><h2>부분출하 기록</h2>${db.shipments.slice().reverse().map(x=>`<div class="record"><strong>${x.house}동</strong><div><b>${fmt(x.count)}수</b><span>${x.date} · ${x.note||'특이사항 없음'}</span></div></div>`).join('')||'<p class="empty">기록이 없습니다.</p>'}</div>`);document.querySelectorAll('[data-house]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.house);shipView()});$('#saveShip').onclick=()=>{const count=Number($('#shipCount').value);if(!count)return;const row={id:uid(),회차ID:db.placementDate,날짜:$('#shipDate').value,일령:age(),동:selected,출하수:count,특이사항:$('#shipNote').value,입력시간:new Date().toISOString(),기기ID:deviceId(),deleted:false};db.shipments.push({id:row.id,date:row.날짜,age:row.일령,house:selected,count,note:row.특이사항});queue('부분출하기록',row);toast('부분출하 저장 완료');shipView()}}
